// Writes the two script files the page loads (plain <script src>, so the page works from file://, a local server and a published artifact):
//   forager-wasm.js : FORAGER_WASM_B64 (forager.wasm in base64) and FORAGER_DEFAULTS (the page's cfg object, the same defaults the Node runners read)
//   pops/pops.js    : FORAGER_POPS, the showcase populations listed in pops/manifest.json (settings from <id>.bin.json, genomes from <id>.bin, test numbers from <id>.log)
// Rerun after every engine rebuild or when a population changes:  node mkbundle.js        Check only (no writing, exit 1 if out of date):  node mkbundle.js --check
const fs = require('fs'), path = require('path');
const here = __dirname, check = process.argv.includes('--check');
const wasm = fs.readFileSync(path.join(here, 'wasm', 'forager.wasm'));
const html = fs.readFileSync(path.join(here, 'forager-lab.html'), 'utf8');
const m = html.match(/var cfg = (\{[^;]*\});/);
if (!m) throw new Error('could not find the cfg object in forager-lab.html');
const defaults = new Function('return ' + m[1])();
const wasmJs = '// generated by mkbundle.js: do not edit\nglobalThis.FORAGER_WASM_B64 = "' + wasm.toString('base64') + '";\nglobalThis.FORAGER_DEFAULTS = ' + JSON.stringify(defaults) + ';\n';
const pc = s => { const mm = s.match(/(\d+)%/); return mm ? +mm[1] : null; };
const popsList = [];
for (const p of JSON.parse(fs.readFileSync(path.join(here, 'pops', 'manifest.json'), 'utf8'))) {
  const bin = fs.readFileSync(path.join(here, 'pops', p.id + '.bin')), saved = JSON.parse(fs.readFileSync(path.join(here, 'pops', p.id + '.bin.json'), 'utf8'));
  const log = fs.readFileSync(path.join(here, 'pops', p.id + '.log'), 'utf8').split('\n'), line = log.find(l => l.startsWith('FINAL seed'));
  if (!line) throw new Error(p.id + '.log has no FINAL line');
  const g = k => { const mm = line.match(new RegExp(k + ' (\\d+)(%?)')); return mm ? +mm[1] : null; };
  const rawPath = path.join(here, '..', '..', p.raw), rawLine = fs.readFileSync(rawPath, 'utf8').split('\n').find(l => l.startsWith(p.rawTag + ' FINAL seed'));
  if (!rawLine) throw new Error('no raw line for ' + p.rawTag);
  if (rawLine.slice(p.rawTag.length + 1) !== line) throw new Error(p.id + ': FINAL line differs from the committed raw line\n  ' + rawLine + '\n  ' + line);
  const cfg = Object.assign({}, saved.cfg); delete cfg.saveTo;
  popsList.push({ id: p.id, title: p.title, story: p.story, seed: saved.seed, cfg, test: { cups: { ticks: g('TEST_BARS_TICKS'), full: g('TEST_BARS_FULL'), drank: g('TEST_BARS_DRANK') }, open: { ticks: g('TEST_NOBARS_TICKS'), full: g('TEST_NOBARS_FULL'), drank: g('TEST_NOBARS_DRANK') } }, raw: p.raw + ' (' + p.rawTag + ')', b64: bin.toString('base64') });
}
const popsJs = '// generated by mkbundle.js: do not edit\nglobalThis.FORAGER_POPS = ' + JSON.stringify(popsList) + ';\n';
const out = [[path.join(here, 'forager-wasm.js'), wasmJs], [path.join(here, 'pops', 'pops.js'), popsJs]];
let stale = false;
for (const [file, text] of out) {
  if (check) { if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text) { console.log('OUT OF DATE', file); stale = true; } else console.log('up to date', file); }
  else { fs.writeFileSync(file, text); console.log('wrote', file, (text.length / 1024).toFixed(0) + ' KB'); }
}
if (stale) process.exit(1);
